import java.util.*;

List<Tache> taches = new ArrayList<>();
taches.add(new Tache(1, "Acheter du pain", false));
taches.add(new Tache(2, "Appeler le medecin", false));
taches.add(new Tache(3, "Arroser les plantes", false));

// Methodes des Sequenced Collections (Java 21) :
System.out.println(taches.getFirst()); // Tache[id=1, titre=Acheter du pain, faite=false]
System.out.println(taches.getLast());  // Tache[id=3, titre=Arroser les plantes, faite=false]

// reversed() : une VUE en ordre inverse, sans copier ni modifier la liste d'origine.
for (Tache t : taches.reversed()) {
    System.out.println(t.id() + " " + t.titre()); // 3, puis 2, puis 1
}

// Affiche les taches de la plus recente a la plus ancienne.
private String afficherInverse() {
    if (taches.isEmpty()) return "(aucune tache)";
    StringBuilder sb = new StringBuilder();
    for (Tache t : taches.reversed()) { // la VUE inversee
        sb.append(t.faite() ? "[x] " : "[ ] ")
          .append(t.id()).append(' ').append(t.titre()).append('\n');
    }
    return sb.toString().strip();
}

// Pratique : un petit resume premier/dernier.
private String resume() {
    if (taches.isEmpty()) return "Liste vide";
    return "Premiere : " + taches.getFirst().titre()
         + " | Derniere : " + taches.getLast().titre();
}

import java.util.*;
import java.util.concurrent.*;

// Simule le chargement du detail d'une tache (une attente reseau).
static String chargerDetail(Tache t) throws InterruptedException {
    Thread.sleep(200); // on "attend" une reponse pendant 200 ms
    return "Detail charge pour : " + t.titre();
}

static List<String> chargerTout(List<Tache> taches) throws InterruptedException {
    // Un executor qui cree UN thread virtuel par tache soumise.
    try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
        List<Future<String>> futurs = new ArrayList<>();
        for (Tache t : taches) {
            futurs.add(executor.submit(() -> chargerDetail(t)));
        }
        // On recupere les resultats une fois tous les chargements lances.
        List<String> resultats = new ArrayList<>();
        for (Future<String> f : futurs) {
            resultats.add(f.resultNow()); // disponible quand le try se ferme
        }
        return resultats;
    } // le try-with-resources attend la fin de tous les threads virtuels
}

import java.util.*;

public final class GestionnaireTaches {
    private final List<Tache> taches = new ArrayList<>(); // Sequenced Collection
    private int prochainId = 1;

    public String traiter(Commande commande) {
        return switch (commande) {
            case Ajouter(String titre) -> {
                Tache t = new Tache(prochainId++, titre, false);
                taches.add(t);
                yield "Ajoutee : " + t.titre();
            }
            case Terminer(int id) -> marquerFaite(id);
            case Lister() -> afficher();
        };
    }

    private String marquerFaite(int id) {
        for (int i = 0; i < taches.size(); i++) {
            if (taches.get(i).id() == id) {
                taches.set(i, taches.get(i).terminer());
                return "Terminee : tache " + id;
            }
        }
        return "Introuvable : tache " + id;
    }

    private String afficher() {
        if (taches.isEmpty()) return "(aucune tache)";
        StringBuilder sb = new StringBuilder();
        for (Tache t : taches) {
            sb.append(t.faite() ? "[x] " : "[ ] ")
              .append(t.id()).append(' ').append(t.titre()).append('\n');
        }
        return sb.toString().strip();
    }

    public List<Tache> taches() {
        return List.copyOf(taches); // copie immuable : on ne fuit pas l'interne
    }
}

import java.util.Scanner;

public class App {
    // Traduit une ligne de texte en Commande.
    static Commande analyser(String ligne) {
        String[] mots = ligne.trim().split("\\s+", 2);
        return switch (mots[0]) {
            case "ajouter"  -> new Ajouter(mots.length > 1 ? mots[1] : "");
            case "terminer" -> new Terminer(Integer.parseInt(mots[1]));
            case "lister"   -> new Lister();
            default -> throw new IllegalArgumentException("commande inconnue : " + mots[0]);
        };
    }

    public static void main(String[] args) {
        var gestionnaire = new GestionnaireTaches();
        var scanner = new Scanner(System.in);
        System.out.println("Commandes : ajouter <titre> | terminer <id> | lister | quitter");
        while (scanner.hasNextLine()) {
            String ligne = scanner.nextLine();
            if (ligne.equals("quitter")) break;
            try {
                System.out.println(gestionnaire.traiter(analyser(ligne)));
            } catch (RuntimeException e) {
                System.out.println("Erreur : " + e.getMessage());
            }
        }
    }
}

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class GestionnaireTachesTest {

    @Test
    void ajouter_puis_lister_garde_l_ordre() {
        var g = new GestionnaireTaches();
        g.traiter(new Ajouter("Acheter du pain"));
        g.traiter(new Ajouter("Arroser les plantes"));
        // La premiere tache ajoutee reste la premiere (Sequenced Collection).
        assertEquals("Acheter du pain", g.taches().getFirst().titre());
        assertEquals("Arroser les plantes", g.taches().getLast().titre());
    }

    @Test
    void terminer_marque_la_tache_comme_faite() {
        var g = new GestionnaireTaches();
        g.traiter(new Ajouter("Appeler le medecin"));
        g.traiter(new Terminer(1));
        assertTrue(g.taches().getFirst().faite());
    }

    @Test
    void titre_vide_est_refuse() {
        // Le constructeur compact de Tache rejette un titre vide.
        assertThrows(IllegalArgumentException.class, () -> new Tache(1, "  ", false));
    }
}

